const winston = require('winston');
const logger = winston.createLogger({ level: 'info', transports: [ new winston.transports.File({ filename: "/home/node/.n8n/logs/n8n.log" }) ], defaultMeta: { workflow: "alice-dms-language-backfill", node: "Code: Acquire Backfill Lock" } });
const redis = require('redis');
const crypto = require('crypto');
// Same lock key as alice-dms-processor / alice-dms-classification-backfill — must never run concurrently (Ollama/RTX 3090 contention).
const LOCK_KEY = 'alice:dms:processor:lock:run';
const LOCK_TTL_MS = 1800000;

let redisPw = ''; try { redisPw = $env.REDIS_PASSWORD || ''; } catch(e) {}
const client = redis.createClient({ socket: { host: 'redis', port: 6379 }, password: redisPw || undefined });
const ownerToken = crypto.randomUUID();
let acquired = false, lockError = false;
try {
  await client.connect();
  const res = await client.set(LOCK_KEY, JSON.stringify({ owner: ownerToken, started_at: new Date().toISOString() }), { NX: true, PX: LOCK_TTL_MS });
  acquired = (res === 'OK');
} catch(e) {
  logger.info('[LangBackfill] Lock acquire error: ' + e.message);
  acquired = false; lockError = true;
} finally {
  await client.quit().catch(() => {});
}

return [{ json: { _lock_acquired: acquired, _lock_error: lockError, lock_owner: acquired ? ownerToken : null } }];

// Read the ORIGINAL webhook payload by node name, NOT $input: the upstream
// "Code: Acquire Backfill Lock" returns a fresh { _lock_acquired, _lock_error,
// lock_owner } object and drops body/query, so $input.first().json.body is
// undefined here and confirm would silently always be false.
const item = $('Webhook: POST /language-backfill').first().json;
const body = item.body || {};
const query = item.query || {};
const confirmRaw = body.confirm !== undefined ? body.confirm : query.confirm;
const CONFIRM = confirmRaw === true || confirmRaw === 'true';

// title only exists in schema for Document/Contract (same restriction as alice-dms-processor's extraction prompt)
const COLLECTIONS = [
  { class: 'Invoice', textField: 'fullText', hasTitle: false },
  { class: 'BankStatement', textField: 'fullText', hasTitle: false },
  { class: 'Document', textField: 'fullText', hasTitle: true },
  { class: 'Email', textField: 'content', hasTitle: false },
  { class: 'SecuritySettlement', textField: 'fullText', hasTitle: false },
  { class: 'Contract', textField: 'fullText', hasTitle: true }
];

const redis = require('redis');
let redisPw = ''; try { redisPw = $env.REDIS_PASSWORD || ''; } catch(e) {}
const client = redis.createClient({ socket: { host: 'redis', port: 6379 }, password: redisPw || undefined });
await client.connect();
try {
  await client.set('alice:dms:language-backfill:run:start_time', Date.now().toString());
  await client.del('alice:dms:language-backfill:run:stats');
  await client.del('alice:dms:language-backfill:run:hits');
  await client.hSet('alice:dms:language-backfill:run:stats', { checked: '0', hits_found: '0', corrected: '0', failed: '0', still_uncertain: '0' });
} finally {
  await client.quit();
}

// Optional override for testing, same payload source as confirm. Falls back to
// the 7200 s default. "Code: Time Check" reads this value back by node name.
const rawMax = body.max_runtime_seconds !== undefined ? body.max_runtime_seconds : query.max_runtime_seconds;
const parsedMax = parseInt(rawMax, 10);
const MAX_RUNTIME_SECONDS = (!isNaN(parsedMax) && parsedMax > 0) ? parsedMax : 7200;

return [{ json: { confirm: CONFIRM, collections: COLLECTIONS, MAX_RUNTIME_SECONDS } }];

const axios = require('axios');
const trigger = $input.first().json;
// Dry-run never calls Ollama (pure heuristic) — health check only matters for confirm runs.
if (!trigger.confirm) {
  return [{ json: { ...trigger, _ollama_ok: true } }];
}
let ollamaOk = false;
try {
  await axios.get('http://ollama-3090:11434/api/tags', { timeout: 5000 });
  ollamaOk = true;
} catch(e) {
  ollamaOk = false;
}
return [{ json: { ...trigger, _ollama_ok: ollamaOk } }];

const redis = require('redis');
let redisPw = ''; try { redisPw = $env.REDIS_PASSWORD || ''; } catch(e) {}
const client = redis.createClient({ socket: { host: 'redis', port: 6379 }, password: redisPw || undefined });
await client.connect();
const owner = $('Code: Acquire Backfill Lock').first().json.lock_owner;
const RELEASE_SCRIPT = `local raw = redis.call('GET', KEYS[1]) if not raw then return 0 end local ok, data = pcall(cjson.decode, raw) if not ok or data.owner ~= ARGV[1] then return 0 end redis.call('DEL', KEYS[1]) return 1`;
try { await client.eval(RELEASE_SCRIPT, { keys: ['alice:dms:processor:lock:run'], arguments: [owner] }); } catch(e) {}
await client.del('alice:dms:language-backfill:run:start_time').catch(() => {});
await client.del('alice:dms:language-backfill:run:stats').catch(() => {});
await client.quit().catch(() => {});

const trigger = $('Code: Init Backfill Run').first().json;
return [{ json: { mode: trigger.confirm ? 'confirm' : 'dry-run', reason: 'ollama_unavailable', error: 'Ollama is not reachable — aborting cleanly before processing any documents. Retry once Ollama is back up; already-corrected documents are unaffected.' } }];

const winston = require('winston');
const logger = winston.createLogger({ level: 'info', transports: [ new winston.transports.File({ filename: "/home/node/.n8n/logs/n8n.log" }) ], defaultMeta: { workflow: "alice-dms-language-backfill", node: "Code: Fetch All Documents" } });
const axios = require('axios');
const trigger = $input.first().json;
const WEAVIATE = 'http://weaviate:8080';
const PAGE = 100;

const allDocs = [];
for (const col of trigger.collections) {
  let cursor = null;
  while (true) {
    const cursorClause = cursor ? `, after: "${cursor}"` : '';
    const titleField = col.hasTitle ? ' title' : '';
    const gql = `{ Get { ${col.class}(limit: ${PAGE}${cursorClause}) { _additional { id } filePath fileName ${col.textField} summary${titleField} } } }`;
    let results;
    try {
      const r = await axios.post(`${WEAVIATE}/v1/graphql`, { query: gql }, { headers: { 'Content-Type': 'application/json' }, timeout: 30000 });
      if (r.data?.errors) {
        logger.warn(`[LangBackfill] GraphQL error for ${col.class}: ${JSON.stringify(r.data.errors)}`);
        break;
      }
      results = r.data?.data?.Get?.[col.class] || [];
    } catch(e) {
      logger.warn(`[LangBackfill] Request failed for ${col.class}: ${e.message}`);
      break;
    }
    if (results.length === 0) break;
    for (const doc of results) {
      allDocs.push({
        weaviate_id: doc._additional?.id,
        class: col.class,
        hasTitle: col.hasTitle,
        filePath: doc.filePath || null,
        fileName: doc.fileName || null,
        fullText: doc[col.textField] || '',
        summary: doc.summary || '',
        title: col.hasTitle ? (doc.title || null) : null,
        confirm: trigger.confirm
      });
    }
    if (results.length < PAGE) break;
    cursor = results[results.length - 1]?._additional?.id;
    if (!cursor) break;
  }
  logger.info(`[LangBackfill] ${col.class}: fetched ${allDocs.filter(d => d.class === col.class).length} documents`);
}

logger.info(`[LangBackfill] Total documents queued for language check: ${allDocs.length}`);
if (allDocs.length === 0) {
  return [{ json: { _empty: true } }];
}
return allDocs.map(d => ({ json: { ...d, _empty: false } }));

