const winston = require('winston');
const logger = winston.createLogger({ level: 'info', transports: [ new winston.transports.File({ filename: "/home/node/.n8n/logs/n8n.log" }) ], defaultMeta: { workflow: "alice-dms-language-backfill", node: "Code: Time Check" } });
const redis = require('redis');
let redisPw = ''; try { redisPw = $env.REDIS_PASSWORD || ''; } catch(e) {}
const client = redis.createClient({ socket: { host: 'redis', port: 6379 }, password: redisPw || undefined });
let timeLimitReached = false;
// Read the limit from Init by node name (the direct input is Split In Batches).
// Previously hardcoded here, which silently ignored the value Init emitted.
let maxRuntime = 7200;
try {
  const initMax = parseInt($('Code: Init Backfill Run').first().json.MAX_RUNTIME_SECONDS, 10);
  if (!isNaN(initMax) && initMax > 0) maxRuntime = initMax;
} catch(e) {}
await client.connect();
try {
  const startTimeStr = await client.get('alice:dms:language-backfill:run:start_time');
  if (startTimeStr) {
    const elapsed = (Date.now() - parseInt(startTimeStr)) / 1000;
    timeLimitReached = elapsed >= maxRuntime;
  }
} finally {
  await client.quit();
}

const owner = $('Code: Acquire Backfill Lock').first().json.lock_owner;
const RENEW_SCRIPT = `local raw = redis.call('GET', KEYS[1]) if not raw then return 0 end local ok, data = pcall(cjson.decode, raw) if not ok or data.owner ~= ARGV[1] then return 0 end data.last_heartbeat = ARGV[2] redis.call('SET', KEYS[1], cjson.encode(data), 'PX', ARGV[3]) return 1`;
let lockLost = false;
const renewClient = redis.createClient({ socket: { host: 'redis', port: 6379 }, password: redisPw || undefined });
try {
  await renewClient.connect();
  const res = await renewClient.eval(RENEW_SCRIPT, { keys: ['alice:dms:processor:lock:run'], arguments: [owner, new Date().toISOString(), '1800000'] });
  lockLost = (res !== 1);
  if (lockLost) logger.info('[LangBackfill] Lock ownership lost - aborting run');
} catch(e) {
  lockLost = true;
} finally {
  await renewClient.quit().catch(() => {});
}
const item = $input.first().json;
return [{ json: { ...item, _time_limit_reached: timeLimitReached, _lock_lost: lockLost } }];

const winston = require('winston');
const logger = winston.createLogger({ level: 'info', transports: [ new winston.transports.File({ filename: "/home/node/.n8n/logs/n8n.log" }) ], defaultMeta: { workflow: "alice-dms-language-backfill", node: "Code: Heuristic Check" } });
const redis = require('redis');
const doc = $input.first().json;

let threshold = 0.3; try { const t = parseFloat($env.DMS_LANGUAGE_HEURISTIC_THRESHOLD); if (!isNaN(t)) threshold = t; } catch(e) {}

// Same lightweight local heuristic as alice-dms-language-check — kept identical so dry-run
// hits and the fix's own flagging never drift apart (PROJ-79 tech decision).
const ENGLISH_MARKERS = new Set(['the','and','of','to','in','for','is','on','with','as','by','at','from','this','that','was','were','are','be','been','has','have','had','it','an','a','or','not','but','which','their','its','if','you','your','we','our','will','would','can','could','should','about','into','than','then','they','he','she','his','her','them','also','all','any','other','more','most','such','no','only','so','when','what','who','how','where']);
function englishRatio(text) {
  const words = (text || '').toLowerCase().match(/[a-zäöüß]+/g) || [];
  if (words.length < 6) return null;
  let hits = 0;
  for (const w of words) if (ENGLISH_MARKERS.has(w)) hits++;
  return hits / words.length;
}
function looksEnglish(text) {
  const ratio = englishRatio(text);
  if (ratio === null) return false;
  return ratio >= threshold;
}

const redisClient = redis.createClient({ socket: { host: 'redis', port: 6379 }, password: (() => { try { return $env.REDIS_PASSWORD || ''; } catch(e) { return ''; } })() || undefined });
await redisClient.connect();
try {
  await redisClient.hIncrBy('alice:dms:language-backfill:run:stats', 'checked', 1);
} finally {
  await redisClient.quit();
}

const summaryHit = looksEnglish(doc.summary);
const titleHit = doc.hasTitle ? looksEnglish(doc.title) : false;
const isHit = summaryHit || titleHit;

return [{ json: { ...doc, _is_hit: isHit, _summary_hit: summaryHit, _title_hit: titleHit } }];

