  // One report entry per affected field (PROJ-79 AC: fileName, collection, betroffenes Feld, aktueller Wert)
  const entries = [];
  if (doc._summary_hit) entries.push({ fileName: doc.fileName, filePath: doc.filePath, collection: doc.class, field: 'summary', value: doc.summary });
