  for (const entry of entries) {
    await client.rPush('alice:dms:language-backfill:run:hits', JSON.stringify(entry));
  }
} finally {
  await client.quit();
}
return [{ json: { _outcome: 'hit_reported', filePath: doc.filePath, class: doc.class } }];

