const winston = require('winston');
const logger = winston.createLogger({ level: 'info', transports: [ new winston.transports.File({ filename: "/home/node/.n8n/logs/n8n.log" }) ], defaultMeta: { workflow: "alice-dms-language-backfill", node: "Code: Apply Correction" } });
const axios = require('axios');
const redis = require('redis');

const langResult = $input.first().json; // { summary, title, languageUncertain, language_retried, extracted }
const doc = $('Code: Prep Language Check Input').first().json._doc;
const WEAVIATE_URL = 'http://weaviate:8080';

let redisPw = ''; try { redisPw = $env.REDIS_PASSWORD || ''; } catch(e) {}
const client = redis.createClient({ socket: { host: 'redis', port: 6379 }, password: redisPw || undefined });
await client.connect();

async function incr(field, by) {
  try { await client.hIncrBy('alice:dms:language-backfill:run:stats', field, by || 1); } catch(e) {}
}

try {
  const hasResult = langResult && typeof langResult === 'object' && !langResult.error;
  if (!hasResult) {
    throw new Error('language_check_failed');
  }

  const properties = { summary: langResult.summary || doc.summary, languageUncertain: !!langResult.languageUncertain };
  if (doc.hasTitle && langResult.title !== null && langResult.title !== undefined) {
    properties.title = langResult.title;
  }

  // Reuse existing object — field-only PATCH, no collection change, no insert/delete (PROJ-79: no duplicate-risk
  // path exists here since the document type never changes).
  await axios.patch(`${WEAVIATE_URL}/v1/objects/${doc.class}/${doc.weaviate_id}`, { properties }, { headers: { 'Content-Type': 'application/json' }, timeout: 15000 });

  await incr('corrected', 1);
  if (properties.languageUncertain) await incr('still_uncertain', 1);

  return [{ json: { _outcome: 'corrected', filePath: doc.filePath, class: doc.class, languageUncertain: properties.languageUncertain } }];
} catch(e) {
  logger.warn('[LangBackfill] Correction failed for ' + (doc.filePath || '') + ' (' + doc.class + '/' + doc.weaviate_id + '): ' + e.message);
  await incr('failed', 1);
  return [{ json: { _outcome: 'failed', filePath: doc.filePath, class: doc.class, error: e.message } }];
} finally {
  await client.quit().catch(() => {});
}

const winston = require('winston');
const logger = winston.createLogger({ level: 'info', transports: [ new winston.transports.File({ filename: "/home/node/.n8n/logs/n8n.log" }) ], defaultMeta: { workflow: "alice-dms-language-backfill", node: "Code: Build & Send Summary" } });
const redis = require('redis');
let redisPw = ''; try { redisPw = $env.REDIS_PASSWORD || ''; } catch(e) {}
const client = redis.createClient({ socket: { host: 'redis', port: 6379 }, password: redisPw || undefined });
await client.connect();

const trigger = $('Code: Init Backfill Run').first().json;
const startTimeStr = await client.get('alice:dms:language-backfill:run:start_time');
const stats = await client.hGetAll('alice:dms:language-backfill:run:stats');
const runtime_seconds = startTimeStr ? Math.floor((Date.now() - parseInt(startTimeStr)) / 1000) : 0;

let hits = [];
if (!trigger.confirm) {
  const raw = await client.lRange('alice:dms:language-backfill:run:hits', 0, -1);
  hits = raw.map(s => { try { return JSON.parse(s); } catch(e) { return null; } }).filter(Boolean);
}

await client.del('alice:dms:language-backfill:run:start_time').catch(() => {});
await client.del('alice:dms:language-backfill:run:stats').catch(() => {});
await client.del('alice:dms:language-backfill:run:hits').catch(() => {});

const owner = $('Code: Acquire Backfill Lock').first().json.lock_owner;
const RELEASE_SCRIPT = `local raw = redis.call('GET', KEYS[1]) if not raw then return 0 end local ok, data = pcall(cjson.decode, raw) if not ok or data.owner ~= ARGV[1] then return 0 end redis.call('DEL', KEYS[1]) return 1`;
try { await client.eval(RELEASE_SCRIPT, { keys: ['alice:dms:processor:lock:run'], arguments: [owner] }); } catch(e) {}
await client.quit().catch(() => {});

const item = $input.first().json || {};
const reason = item._lock_lost ? 'lock_lost' : (item._time_limit_reached ? 'time_limit_reached' : 'completed');

const result = {
  mode: trigger.confirm ? 'confirm' : 'dry-run',
  reason,
  total_checked: parseInt(stats.checked || '0'),
  hits_found: parseInt(stats.hits_found || '0'),
  runtime_seconds
};
if (trigger.confirm) {
  result.corrected = parseInt(stats.corrected || '0');
  result.failed = parseInt(stats.failed || '0');
  result.still_uncertain = parseInt(stats.still_uncertain || '0');
} else {
  result.hits = hits;
}
logger.info(JSON.stringify({ event: 'alice-dms-language-backfill-complete', ...result }));
return [{ json: result }];
